#ifndef FUZZ_CHAINS_H
#define FUZZ_CHAINS_H

/*
 * The enum is unconditional and the TABLES are not. fuzz.h
 * names a chain in the signature of the one entry point whose
 * caller can know which one it is holding, so every file that
 * includes fuzz.h sees this enum -- and would otherwise also
 * get five static arrays it never names. fuzz.c defines
 * FUZZ_CHAINS_TABLES; nothing else does.
 */
enum fuzz_chain {
	/* The 802.11 element chain: three header shapes selected by
	 * the id, Fragment elements that continue the one before
	 * them, and containers whose body is a chain of its own. The
	 * other formats have none of that, which is not a
	 * simplification here -- it is what their walkers do. */
	FUZZ_CHAIN_ELEM = 0,
	FUZZ_CHAIN_WPS,
	FUZZ_CHAIN_DPP,
	FUZZ_CHAIN_P2P,
	FUZZ_CHAIN_NAN,
	FUZZ_NUM_CHAINS
};

#endif /* FUZZ_CHAINS_H */

/* A guard of its own, so the tables arrive whatever order the
 * two includes happen in: fuzz.h pulls this header in for the
 * enum alone, and fuzz.c then asks for the rest. */
